def solve(nums):
    n = len(nums)
    ans = [1] * n

    for i in range(n):
        prod = 1
        for j in range(n):
            if j != i:
                prod *= nums[j]
        ans[i] = prod

    return ans

def solve(target, nums):
    n = len(nums)
    best = n + 1

    for i in range(n):
        total = 0
        for j in range(i, n):
            total += nums[j]
            if total >= target:
                best = min(best, j - i + 1)
                break

    return 0 if best == n + 1 else best

def solve(nums):
    nums.sort()
    expect = 1

    for x in nums:
        if x < expect:
            continue
        if x == expect:
            expect += 1

    return expect

