def solve(nums):
    n = len(nums)

    i = 0
    while i < n:
        v = nums[i]
        correct = v - 1
        if 1 <= v <= n and nums[correct] != v:
            nums[i], nums[correct] = nums[correct], nums[i]
        else:
            i += 1

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1
